const paginationInfo = await browserjs(tabId, () => {
  const pagination = document.querySelector('[aria-label*="pagination"], [class*="pagination"], nav[role="navigation"]');
  const buttons = Array.from(document.querySelectorAll('button, a')).filter(el => {
