  // Total results text
  const resultsCountText = Array.from(document.querySelectorAll('*')).find(el => {
    return el.children.length === 0 && /\d+\s+(results|items|products)/i.test(el.textContent);
  })?.textContent?.trim();

  return {
    resultsCountText,
    buttons
  };
});
console.log("Pagination info:", JSON.stringify(paginationInfo, null, 2));
